def run(edits=None):
    with tempfile.TemporaryDirectory(prefix='duo-extraction-bridge-') as d:
        work=Path(d);sources=dict(S);sources['ls/augment/com/TestExtractionBridge.java']=TEST
        for name in FILES:sources['ls/augment/com/'+name]=(edits or {}).get(name,(SRC/name).read_text(encoding='utf-8'))
        paths=[]
        for name,text in sources.items():
            p=work/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding='utf-8');paths.append(str(p))
        c=subprocess.run([str(JDK/'javac.exe'),'-J-Dfile.encoding=UTF-8','-J-Duser.language=en','--release','17','-encoding','UTF-8','-d',str(work/'classes'),*paths],capture_output=True,text=True,encoding='utf-8',errors='replace',timeout=45)
        if c.returncode:raise AssertionError(c.stdout+c.stderr)
        return subprocess.run([str(JDK/'java.exe'),'-Dfile.encoding=UTF-8','-cp',str(work/'classes'),'ls.augment.com.TestExtractionBridge'],capture_output=True,text=True,encoding='utf-8',errors='replace',timeout=30)

def main():
    p=argparse.ArgumentParser();p.add_argument('--negative-controls',action='store_true');a=p.parse_args();r=run()
    if r.returncode:raise AssertionError(r.stdout+r.stderr)
    print(r.stdout,end='')
    if a.negative_controls:
        source=(SRC/'AtomicWorkbenchExtractionSystemBridge.java').read_text(encoding='utf-8')
        for before,after,witness in [
            ('Binder.getCallingUid()!=1000','false','unauthenticated callback read source'),
            ('if(!current()||active!=r||!r.fresh(SystemClock.elapsedRealtime()))return;out=listener;','if(false)return;out=listener;','stale completed body published'),
            ('else AtomicWorkbenchExtractionPresentation.show(service,result,r);','else {}','fallback lost frozen request'),
            ('return (flags & ~0x10) == IBinder.FLAG_ONEWAY;', 'return true;', 'unauthenticated callback read source'),
            ('if(code!=1&&code!=2)return false;', 'if(code!=1&&code!=2)return false;if(reply!=null)reply.writeInt(0);', 'oneway callback wrote a response'),
        ]:
            assert source.count(before)==1,before;r=run({'AtomicWorkbenchExtractionSystemBridge.java':source.replace(before,after)})
            if r.returncode==0 or witness not in r.stdout+r.stderr:raise AssertionError(r.stdout+r.stderr)
            print('PASS bridge behavior negative: '+witness)
    print('PHONE PENDING; ACTUAL PRESENTATION ACCEPTANCE OWNED BY UI SUITE; NO ADB/GRADLE')

if __name__=='__main__':main()
